import * as THREE from './vendor/three.module.js';
import {groundHeight} from './terrain.js';

// Coherent, original Norwegian roadside vignettes. Shared geometry/material
// batches keep a whole course's extra detail under 35 draw calls.
export function buildRoadsideDetails({scene,track,terrainGeometry,seed=9301}){
 let state=Number(seed)>>>0;const random=()=>((state=(1664525*state+1013904223)>>>0)/4294967296);
 const root=new THREE.Group();root.name='Picnic overlooks, hikers and rally spectators';scene.add(root);
 const night=track.config.id==='aurora',mat=(color,extra={})=>new THREE.MeshStandardMaterial({color,roughness:.91,flatShading:true,...extra});
 const materials={wood:mat(0x937653),dark:mat(0x33403f),stone:mat(0x89958d),red:mat(0xc44340),cream:mat(0xf0e9d7),teal:mat(0x58b6ae),yellow:mat(0xe8b84e),blue:mat(0x3a719b),face:mat(0xd6ad88),green:mat(0x355c49),metal:mat(0x8daba9),roof:mat(0x394849)};
 const triangle=new THREE.BufferGeometry();triangle.setAttribute('position',new THREE.Float32BufferAttribute([-.5,.5,0,.5,.5,0,0,-.5,0],3));triangle.computeVertexNormals();
 const geometries={box:new THREE.BoxGeometry(1,1,1),rock:new THREE.IcosahedronGeometry(1,0),pole:new THREE.CylinderGeometry(1,1,1,7),triangle};
 const batches=new Map(),dummy=new THREE.Object3D(),matrix=new THREE.Matrix4();
 const placedSites=[],stats={overlooks:0,benches:0,spectators:0,flags:0,cairns:0,signposts:0,timberShelters:0,logs:0,bunting:0,birds:0,drawCalls:0,instances:0};
 const road=track.roadSamples||track.samples,clearance=track.config.width/2+6,finish=track.at(track.length),finishDirection=finish.t.clone().setY(0).normalize();
 function roadDistance(x,z){let best=Infinity;for(let i=1;i<road.length;i++){const a=road[i-1].p,b=road[i].p,dx=b.x-a.x,dz=b.z-a.z,t=Math.max(0,Math.min(1,((x-a.x)*dx+(z-a.z)*dz)/(dx*dx+dz*dz||1)));best=Math.min(best,(x-a.x-t*dx)**2+(z-a.z-t*dz)**2);}return Math.sqrt(best);}
 function excludedFinish(x,z,radius){const dx=x-finish.p.x,dz=z-finish.p.z,along=dx*finishDirection.x+dz*finishDirection.z,cross=dx*finish.r.x+dz*finish.r.z;return along>-150-radius&&along<500+radius&&Math.abs(cross)<95+radius;}
 function ground(x,z){return groundHeight(terrainGeometry,x,z);}
 function site(s,side,radius,kind,offset=0){if(s<12||s>track.length-170)return null;const f=track.at(s),distance=side*(clearance+radius+3+offset),x=f.p.x+f.r.x*distance,z=f.p.z+f.r.z*distance,y=ground(x,z),minimum=roadDistance(x,z);if(y<4||minimum<clearance+radius||excludedFinish(x,z,radius))return null;
  const heights=[y,ground(x-radius,z),ground(x+radius,z),ground(x,z-radius),ground(x,z+radius)],spread=Math.max(...heights)-Math.min(...heights);if(!Number.isFinite(y)||spread>radius*.85)return null;
  if(placedSites.some(p=>Math.hypot(p.x-x,p.z-z)<p.radius+radius+4))return null;
  const p={s,x,y,z,yaw:-f.yaw,radius,kind,minimumRoadDistance:minimum,slope:spread/(radius*2),maxGround:Math.max(...heights),minGround:Math.min(...heights)};return p;
 }
 function commitSite(p){placedSites.push(p);return p;}
 function base(p,y=p.y){dummy.position.set(p.x,y,p.z);dummy.rotation.set(0,p.yaw,0);dummy.scale.setScalar(1);dummy.updateMatrix();return dummy.matrix.clone();}
 function part(shape,color,x,y,z,sx,sy,sz,rx=0,ry=0,rz=0,parent=null){const key=shape+':'+color;let batch=batches.get(key);if(!batch){batch={geometry:geometries[shape],material:materials[color],matrices:[]};batches.set(key,batch);}dummy.position.set(x,y,z);dummy.rotation.set(rx,ry,rz,'YXZ');dummy.scale.set(sx,sy,sz);dummy.updateMatrix();matrix.copy(dummy.matrix);if(parent)matrix.premultiply(parent);batch.matrices.push(matrix.clone());}
 function worldPoint(p,x,z){return{x:p.x+Math.cos(p.yaw)*x+Math.sin(p.yaw)*z,z:p.z-Math.sin(p.yaw)*x+Math.cos(p.yaw)*z};}
 function postOnTerrain(p,x,z,top,width=.17){const q=worldPoint(p,x,z),bottom=ground(q.x,q.z)-.09;part('box','wood',q.x,(bottom+top)/2,q.z,width,Math.max(.12,top-bottom),width);}
 function bench(parent,x,z,y=0,angle=0){dummy.position.set(x,y,z);dummy.rotation.set(0,angle,0);dummy.scale.setScalar(1);dummy.updateMatrix();const b=parent.clone().multiply(dummy.matrix);part('box','wood',0,.67,0,2.65,.16,.69,0,0,0,b);for(const side of [-1,1]){part('box','dark',side*.94,.31,0,.15,.65,.59,0,0,0,b);part('box','dark',side*.94,.95,.29,.12,.8,.12,0,0,-.09,b);}part('box','wood',0,1.19,.34,2.65,.30,.11,-.09,0,0,b);stats.benches++;}
 function person(parent,x,z,color,pose=0,y=0){dummy.position.set(x,y,z);dummy.rotation.set(0,(random()-.5)*.4,0);dummy.scale.setScalar(1.10+random()*.15);dummy.updateMatrix();const b=parent.clone().multiply(dummy.matrix);part('box','dark',-.17,.45,0,.21,.88,.25,0,0,.02,b);part('box','dark',.17,.45,0,.21,.88,.25,0,0,-.02,b);part('box',color,0,1.13,0,.63,.63,.4,0,0,0,b);part('rock','face',0,1.72,-.025,.25,.30,.24,0,0,0,b);part('box',color,0,1.97,.01,.51,.13,.48,0,0,0,b);
  for(const side of [-1,1]){const raised=pose===1||pose===2&&side===1;part('box',color,side*(raised?.52:.42),raised?1.47:1.07,0,.20,.66,.22,0,0,side*(raised?-.65:.13),b);part('rock','face',side*(raised?.73:.47),raised?1.72:.74,0,.12,.13,.12,0,0,0,b);}if(pose===3)part('box','dark',0,1.55,-.36,.40,.25,.20,0,0,0,b);stats.spectators++;
 }
 const flagAnchors=[];
 function flag(p,x,z,height=5.8){const q=worldPoint(p,x,z),y=ground(q.x,q.z);part('pole','metal',q.x,y+height*.5,q.z,.067,height,.067);part('rock','metal',q.x,y+height+.08,q.z,.13,.13,.13);flagAnchors.push({x:q.x,y:y+height-.18,z:q.z,yaw:p.yaw+.5});stats.flags++;}
 function bunting(parent,x,z,width=7,y=3.2,groundSite=null){for(const side of [-1,1]){if(groundSite)postOnTerrain(groundSite,x+side*width/2,z,groundSite.y+y,.13);else part('box','wood',x+side*width/2,y*.5,z,.13,y,.13,0,0,0,parent);}const n=11;for(let i=0;i<n;i++){const t=i/(n-1),h=y-.43*Math.sin(t*Math.PI),nextY=y-.43*Math.sin(Math.min(1,t+1/(n-1))*Math.PI);part('triangle',['red','cream','teal','yellow'][i%4],x-width/2+width*t,h-.28,z,.50,.61,1,0,0,0,parent);if(i<n-1){const dz=nextY-h,length=width/(n-1);part('box','dark',x-width/2+width*(t+.5/(n-1)),(h+nextY)/2,z,.026,Math.hypot(length,dz),.026,0,0,-Math.atan2(length,dz),parent);}}stats.bunting+=n;}
 function overlook(p){commitSite(p);let deckY=p.maxGround+.25;for(const x of [-4.4,0,4.4])for(const z of [-3.6,0,3.6]){const q=worldPoint(p,x,z);deckY=Math.max(deckY,ground(q.x,q.z)+.25);}const b=base(p,deckY);for(let i=0;i<11;i++)part('box','wood',-4+i*.8,0,0,.76,.18,7.2,0,0,0,b);for(const x of [-3.7,3.7])for(const z of [-3.1,3.1])postOnTerrain(p,x,z,deckY+.02,.29);
  // Railings face the valley; the roadside edge remains open like a pull-off.
  for(let x=-4;x<=4;x+=2){part('box','dark',x,.68,3.55,.13,1.4,.13,0,0,0,b);}for(const y of [.66,1.3])part('box','wood',0,y,3.55,8.25,.12,.12,0,0,0,b);
  bench(b,-2.4,1.8,0,Math.PI);bench(b,2.1,1.8,0,Math.PI);part('box','wood',0,.9,.8,1.9,.16,1.5,0,0,0,b);for(const x of [-.6,.6])part('box','dark',x,.42,.8,.15,.84,.8,0,0,0,b);
  person(b,-2.9,-1.8,'yellow',2);person(b,-1.1,-2,'red',3);person(b,1.6,-1.9,'teal',1);person(b,3.1,-1.6,'blue',0);bunting(b,0,2.8,7.5,3.4);flag(p,-4.8,2.9,6);stats.overlooks++;
 }
 function crowd(p){commitSite(p);const b=base(p),colors=['red','teal','yellow','blue','cream'];for(let i=0;i<7;i++){const x=-3.3+i*1.1,z=(i%2)*.85,q=worldPoint(p,x,z);person(b,x,z,colors[i%colors.length],i%4,ground(q.x,q.z)-p.y);}flag(p,-4.4,1.2,5.4);bunting(b,0,2.3,8.8,3.2,p);}
 function trail(p){commitSite(p);const b=base(p);part('box','wood',0,1.65,0,.22,3.3,.22,0,0,0,b);part('box','green',.42,2.69,0,2.7,.47,.15,0,0,0,b);part('box','cream',.03,2.69,-.085,1.50,.055,.022,0,0,0,b);part('box','green',-.37,2.07,0,2.30,.42,.15,0,0,0,b);part('box','cream',-.6,2.07,-.086,1.2,.053,.024,0,0,0,b);
  // White directional chevrons remain readable at racing distance.
  for(const dir of [-1,1]){const x=dir===1?1.38:-1.10,y=dir===1?2.69:2.07;for(const flip of [-1,1])part('box','cream',x,y+flip*.065,-.09,.19,.04,.025,0,0,-dir*flip*.62,b);}part('box','red',0,3.02,-.13,.17,.22,.023,0,0,0,b);stats.signposts++;
  const q=worldPoint(p,1.15,.2),cairnY=ground(q.x,q.z)-p.y;for(let i=0;i<4;i++)part('rock','stone',1.15,cairnY+.2+i*.27,.2,.72-i*.13,.23,.57-i*.095,0,i*.72,0,b);part('box','red',1.15,cairnY+.91,-.04,.19,.12,.025,0,0,0,b);stats.cairns++;
 }
 function cairn(p){commitSite(p);const b=base(p);for(let i=0;i<5;i++)part('rock','stone',Math.sin(i)*.08,.18+i*.28,0,.88-i*.14,.26,.71-i*.115,0,i*.9,0,b);part('box','red',-.06,1.28,-.23,.22,.10,.025,0,0,0,b);part('box','red',-.06,1.18,-.23,.07,.17,.025,0,0,0,b);stats.cairns++;}
 function timberShelter(p){commitSite(p);const y=p.maxGround+.10,b=base(p,y);part('box','wood',0,0,0,4.6,.20,4.2,0,0,0,b);for(const x of [-2,2])for(const z of [-1.7,1.7])postOnTerrain(p,x,z,y+3.2,.24);part('box','red',0,1.38,1.82,4.1,2.75,.2,0,0,0,b);for(const side of [-1,1])part('box','red',side*2.06,1.34,.30,.19,2.67,3.15,0,0,0,b);for(const side of [-1,1])part('box','roof',side*1.22,3.20,0,2.75,.22,4.9,0,0,side*.35,b);part('box','cream',0,2.64,-1.75,4.34,.17,.17,0,0,0,b);bench(b,0,.88);for(let row=0;row<3;row++)for(let i=0;i<4-row;i++){part('pole','wood',-1.1+i*.55+row*.28,.27+row*.43,-.4,.25,1.3,.25,Math.PI/2,0,0,b);stats.logs++;}stats.timberShelters++;}
 // The first group gives the start line life. Vignettes then alternate at
 // selected overlooks, leaving long uncluttered stretches between them.
 for(const fraction of [.022,.20,.41,.64,.84]){let chosen=null;for(const shift of [0,20,-20,40,-40])for(const side of [-1,1]){if(chosen)break;const p=site(Math.max(35,track.length*fraction)+shift,side,6,'spectators');if(p){crowd(p);chosen=p;}}}
 for(const fraction of [.13,.34,.56,.76]){let chosen=null;for(const shift of [0,25,-25,50,-50,75])for(const side of [1,-1]){if(chosen)break;const p=site(track.length*fraction+shift,side,7,'picnic overlook',1);if(p){overlook(p);chosen=p;}}}
 for(let s=125,i=0;s<track.length-200;s+=150,i++){const p=site(s,i%2?1:-1,2,i%3===0?'trail sign':'painted cairn');if(p){if(i%3===0)trail(p);else cairn(p);}}
 for(const fraction of [.28,.69]){for(const side of [-1,1]){const p=site(track.length*fraction,side,5.6,'timber shelter',2);if(p&&p.y<340){timberShelter(p);break;}}}
 for(const [name,batch] of batches){const mesh=new THREE.InstancedMesh(batch.geometry,batch.material,batch.matrices.length);mesh.name='Roadside '+name;mesh.castShadow=!name.startsWith('triangle:');mesh.receiveShadow=true;if(name.startsWith('triangle:'))mesh.material.side=THREE.DoubleSide;for(let i=0;i<batch.matrices.length;i++)mesh.setMatrixAt(i,batch.matrices[i]);mesh.computeBoundingSphere();root.add(mesh);stats.drawCalls++;stats.instances+=batch.matrices.length;}
 const wind={value:0};
 if(flagAnchors.length){const geometry=new THREE.PlaneGeometry(3.3,2.4,14,8);geometry.translate(1.65,-1.20,0);const material=mat(0xffffff,{side:THREE.DoubleSide,emissive:0xffffff,emissiveIntensity:night?.10:.015});material.onBeforeCompile=shader=>{shader.uniforms.roadsideTime=wind;shader.vertexShader='uniform float roadsideTime;\nvarying vec2 flagUV;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nflagUV = uv; transformed.z += uv.x * (sin(uv.x * 7.0 - roadsideTime * 2.8) * 0.21 + sin(uv.x * 14.0 - roadsideTime * 4.3) * 0.075);');shader.fragmentShader='varying vec2 flagUV;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\nvec3 flagColor = vec3(0.65, 0.018, 0.035); float vx = abs(flagUV.x - 0.36364); float hy = abs(flagUV.y - 0.5); if (vx < 0.09091 || hy < 0.125) flagColor = vec3(0.96); if (vx < 0.04545 || hy < 0.0625) flagColor = vec3(0.015, 0.04, 0.15); diffuseColor.rgb *= flagColor;');};material.customProgramCacheKey=()=> 'norwegian-flags-v1';const flags=new THREE.InstancedMesh(geometry,material,flagAnchors.length);flags.name='Wind-blown Norwegian flags';for(let i=0;i<flagAnchors.length;i++){const p=flagAnchors[i];dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(0,p.yaw,0);dummy.scale.setScalar(1);dummy.updateMatrix();flags.setMatrixAt(i,dummy.matrix);}flags.computeBoundingSphere();root.add(flags);stats.drawCalls++;stats.instances+=flagAnchors.length;}
 const birdGeometry=new THREE.BufferGeometry();birdGeometry.setAttribute('position',new THREE.Float32BufferAttribute([0,0,0,-1.5,.18,.45,-.55,0,-.20,0,0,0,.55,0,-.20,1.5,.18,.45],3));birdGeometry.computeVertexNormals();const birds=new THREE.InstancedMesh(birdGeometry,mat(night?0xc2c8cf:0x455153,{side:THREE.DoubleSide}),7),birdCentre=track.at(track.length*.49).p;birds.name='Birds over the valley';birds.frustumCulled=false;root.add(birds);stats.birds=7;stats.drawCalls++;stats.instances+=7;
 function update(time){wind.value=time;for(let i=0;i<7;i++){const a=time*(.045+i*.001)+i*.8,r=28+i*8;dummy.position.set(birdCentre.x+Math.cos(a)*r,birdCentre.y+48+i*2+Math.sin(time*.7+i)*1.2,birdCentre.z+Math.sin(a)*r);dummy.rotation.set(Math.sin(time*1.7+i)*.07,-a+Math.PI/2,-.16);dummy.scale.setScalar(1);dummy.updateMatrix();birds.setMatrixAt(i,dummy.matrix);}birds.instanceMatrix.needsUpdate=true;}
 update(0);return{update,stats,placedSites,root};
}
